        with open(today_file, 'a') as f:
            f.write(json.dumps(record) + '\n')
        return memory_id
    except Exception as e:
        print(f"Failed to capture memory: {e}")
        return None

def get_raw_memories(start_date=None, end_date=None):
    """
    Retrieve raw memories from the raw store within a date range.

    Args:
        start_date (str, optional): Start date in YYYY-MM-DD format. Defaults to earliest.
        end_date (str, optional): End date in YYYY-MM-DD format. Defaults to today.

    Returns:
        list: List of memory dictionaries.
    """
    _ensure_raw_dir()

    if start_date is None:
        start_date = "1970-01-01"
    if end_date is None:
        end_date = datetime.utcnow().strftime("%Y-%m-%d")

    memories = []
    try:
        current = datetime.strptime(start_date, "%Y-%m-%d")
        end = datetime.strptime(end_date, "%Y-%m-%d")

        while current <= end:
            date_str = current.strftime("%Y-%m-%d")
            file_path = os.path.join(RAW_DIR, f"{date_str}.jsonl")
